protected boolean shouldSkipOriginalInsertMatchingCharges()
{
    boolean ret = next shouldSkipOriginalInsertMatchingCharges();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && 
        parameters.ModuleType == MarkupModuleType::Cust)
    {
        return true;
    }

    return ret;
}

protected void insertMatchingCharges()
{
    next insertMatchingCharges();

    if (this.shouldSkipOriginalInsertMatchingCharges())
    {
        List matchedAutoChargeRecIdList = GUPAutoChargeMatchingHelper::findAllMatchedAutoCharges(parameters);

        ListEnumerator enumerator = matchedAutoChargeRecIdList.getEnumerator();
        MarkupAutoTable markupAutoTable;
        while(enumerator.moveNext())
        {
            markupAutoTable = MarkupAutoTable::findMarkupAutoTableByRecId(str2int64(enumerator.current()));
            this.insertForMarkupAutoTable(markupAutoTable);
        }
    }
}
